import React from 'react';
import { SalesChannel } from '../../types/dashboard';

interface ChannelSplitChartProps {
    data: SalesChannel[];
    isLoading?: boolean;
}

/**
 * Channel Split Chart
 * A simple donut-style chart showing POS / Online / Delivery split.
 */
export const ChannelSplitChart: React.FC<ChannelSplitChartProps> = ({ data, isLoading }) => {
    if (isLoading || !data || data.length === 0) {
        return (
            <div className="h-48 flex items-center justify-center">
                <div className="w-8 h-8 border-2 border-slate-200 border-t-emerald-500 rounded-full animate-spin" />
            </div>
        );
    }

    const total = data.reduce((sum, item) => sum + item.sales, 0);
    const colors = ['#10B981', '#3B82F6', '#F59E0B', '#8B5CF6'];

    let cumulativePercentage = 0;

    return (
        <div className="flex flex-col items-center">
            <div className="relative w-40 h-40">
                <svg viewBox="0 0 100 100" className="w-full h-full -rotate-90">
                    {data.map((item, index) => {
                        const percentage = (item.sales / total) * 100;
                        const strokeDasharray = `${percentage} ${100 - percentage}`;
                        const strokeDashoffset = -cumulativePercentage;
                        cumulativePercentage += percentage;

                        return (
                            <circle
                                key={item.channel}
                                cx="50"
                                cy="50"
                                r="40"
                                fill="transparent"
                                stroke={colors[index % colors.length]}
                                strokeWidth="12"
                                strokeDasharray={strokeDasharray}
                                strokeDashoffset={strokeDashoffset}
                                pathLength="100"
                                className="transition-all duration-1000 ease-out"
                            />
                        );
                    })}
                </svg>
                <div className="absolute inset-0 flex flex-col items-center justify-center">
                    <span className="text-[10px] font-bold text-slate-400 uppercase tracking-tighter">Total</span>
                    <span className="text-sm font-black text-slate-800">${(total / 1000).toFixed(1)}k</span>
                </div>
            </div>

            {/* Legend */}
            <div className="mt-6 grid grid-cols-2 gap-x-6 gap-y-2">
                {data.map((item, index) => (
                    <div key={item.channel} className="flex items-center gap-2">
                        <div
                            className="w-2 h-2 rounded-full"
                            style={{ backgroundColor: colors[index % colors.length] }}
                        />
                        <div className="flex flex-col">
                            <span className="text-[10px] font-bold text-slate-800 uppercase">{item.channel}</span>
                            <span className="text-[9px] text-slate-400 font-medium">{item.percentage.toFixed(1)}%</span>
                        </div>
                    </div>
                ))}
            </div>
        </div>
    );
};
