import React from 'react';

export const SalesChart: React.FC = () => {
    const data = [45, 52, 48, 70, 65, 80, 75, 90, 85, 95, 100, 110, 105, 120, 115, 130];
    const labels = ['8AM', '10AM', '12PM', '2PM', '4PM', '6PM', '8PM', '10PM'];

    const height = 240;
    const width = 800;
    const padding = 40;

    const maxValue = Math.max(...data);

    // Function to create smooth Bezier curve path
    const getPath = (isArea = false) => {
        const points = data.map((d, i) => ({
            x: (i / (data.length - 1)) * (width - padding * 2) + padding,
            y: height - (d / maxValue) * (height - padding * 2) - padding
        }));

        let d = `M ${points[0].x} ${points[0].y}`;

        for (let i = 0; i < points.length - 1; i++) {
            const curr = points[i];
            const next = points[i + 1];
            const cp1x = curr.x + (next.x - curr.x) / 2;
            const cp2x = curr.x + (next.x - curr.x) / 2;
            d += ` C ${cp1x} ${curr.y}, ${cp2x} ${next.y}, ${next.x} ${next.y}`;
        }

        if (isArea) {
            d += ` L ${points[points.length - 1].x} ${height - padding}`;
            d += ` L ${points[0].x} ${height - padding} Z`;
        }
        return d;
    };

    return (
        <div className="w-full h-[300px] flex flex-col pt-6">
            <div className="flex-1 relative">
                <svg viewBox={`0 0 ${width} ${height}`} className="w-full h-full overflow-visible">
                    <defs>
                        <linearGradient id="chartGradient" x1="0" y1="0" x2="0" y2="1">
                            <stop offset="0%" stopColor="#10B981" stopOpacity="0.15" />
                            <stop offset="100%" stopColor="#10B981" stopOpacity="0.01" />
                        </linearGradient>
                        <filter id="shadow" height="200%">
                            <feGaussianBlur in="SourceAlpha" stdDeviation="3" />
                            <feOffset dx="0" dy="4" result="offsetblur" />
                            <feComponentTransfer>
                                <feFuncA type="linear" slope="0.1" />
                            </feComponentTransfer>
                            <feMerge>
                                <feMergeNode />
                                <feMergeNode in="SourceGraphic" />
                            </feMerge>
                        </filter>
                    </defs>

                    {/* Grid Lines */}
                    {[0, 0.25, 0.5, 0.75, 1].map((p, i) => {
                        const y = height - padding - p * (height - padding * 2);
                        return (
                            <g key={i}>
                                <line
                                    x1={padding}
                                    y1={y}
                                    x2={width - padding}
                                    y2={y}
                                    className="stroke-slate-100"
                                    strokeWidth="1"
                                />
                                <text
                                    x={padding - 15}
                                    y={y + 3}
                                    textAnchor="end"
                                    className="text-[10px] fill-slate-300 font-bold"
                                >
                                    {Math.round(p * maxValue / 10) * 10}
                                </text>
                            </g>
                        );
                    })}

                    {/* Area under curve */}
                    <path d={getPath(true)} fill="url(#chartGradient)" />

                    {/* Smooth curve line */}
                    <path
                        d={getPath()}
                        fill="none"
                        stroke="#10B981"
                        strokeWidth="3"
                        strokeLinecap="round"
                        strokeLinejoin="round"
                        filter="url(#shadow)"
                    />

                    {/* Interactive points */}
                    {data.map((d, i) => {
                        if (i % 2 !== 0) return null;
                        const x = (i / (data.length - 1)) * (width - padding * 2) + padding;
                        const y = height - (d / maxValue) * (height - padding * 2) - padding;
                        return (
                            <circle
                                key={i}
                                cx={x}
                                cy={y}
                                r="4"
                                className="fill-white stroke-emerald-500 stroke-[3] transition-all duration-300 hover:r-6 cursor-pointer"
                            />
                        );
                    })}

                    {/* X-axis labels */}
                    {labels.map((label, i) => {
                        const x = (i / (labels.length - 1)) * (width - padding * 2) + padding;
                        return (
                            <text
                                key={i}
                                x={x}
                                y={height - padding + 25}
                                textAnchor="middle"
                                className="text-[10px] fill-slate-400 font-black uppercase tracking-widest"
                            >
                                {label}
                            </text>
                        );
                    })}
                </svg>
            </div>
        </div>
    );
};
